"""Markdown summaries generated from aggregate CSVs.

Every number in a summary is read from a CSV written by an evaluate script;
nothing is typed by hand. The hypothesis checks are simple, mechanical tests
on those numbers (stated next to each result), not interpretation.
"""

from __future__ import annotations

import math
from collections.abc import Callable, Iterable

from robust_visual_perception.mot17 import EVENT_MERGE_GAP

HEADER = (
    "<!-- Generated by scripts/plot_results.py from the aggregate CSVs. "
    "Do not edit by hand. -->\n"
)
SEVERITY_ORDER = {"blur": False, "low_light": True, "noise": False}  # reverse?


def _num(value: str, fmt: str = "{:.3f}") -> str:
    try:
        x = float(value)
    except (TypeError, ValueError):
        return value or "–"
    return "–" if math.isnan(x) else fmt.format(x)


def _table(rows: Iterable[dict], columns: list[tuple[str, str, Callable]]) -> str:
    lines = [
        "| " + " | ".join(title for title, _, _ in columns) + " |",
        "|" + "|".join("---" for _ in columns) + "|",
    ]
    for row in rows:
        lines.append("| " + " | ".join(fn(row[key]) for _, key, fn in columns) + " |")
    return "\n".join(lines)


def _f3(v: str) -> str:
    return _num(v)


def _f1(v: str) -> str:
    return _num(v, "{:.1f}")


def _f2(v: str) -> str:
    return _num(v, "{:.2f}")


def _txt(v: str) -> str:
    return v if v != "" else "–"


def _series(rows, kind: str, size: int, metric: str) -> list[float]:
    """Metric from clean through increasing severity for one kind and size."""
    clean = next(
        float(r[metric])
        for r in rows
        if r["kind"] == "clean" and int(r["imgsz"]) == size
    )
    levels = sorted(
        (r for r in rows if r["kind"] == kind and int(r["imgsz"]) == size),
        key=lambda r: float(r["param"]),
        reverse=SEVERITY_ORDER[kind],
    )
    return [clean, *(float(r[metric]) for r in levels)]


def _monotonic_decreasing(values: list[float]) -> bool:
    return all(b <= a for a, b in zip(values, values[1:], strict=False))


def image_summary(rows: list[dict[str, str]]) -> str:
    sizes = sorted({int(r["imgsz"]) for r in rows})
    parts = [HEADER, "# Image experiment (COCO val2017 subset)\n"]
    n_images = int(rows[0]["n_images"])
    n_person = int(rows[0]["n_person_images"])
    n_conditions = len({r["condition"] for r in rows})
    parts.append(
        f"{n_images} images ({n_person} with people, {n_images - n_person} "
        f"without), {n_conditions} conditions, "
        f"input sizes {', '.join(map(str, sizes))}. Decision threshold 0.5, "
        "match IoU 0.5. mAP is on this subset only and is not comparable to "
        "full val2017 numbers.\n"
    )
    for size in sizes:
        subset = [r for r in rows if int(r["imgsz"]) == size]
        parts.append(f"## imgsz {size}\n")
        parts.append(
            _table(
                subset,
                [
                    ("condition", "condition", _txt),
                    ("mAP", "map", _f3),
                    ("person AP", "person_ap", _f3),
                    ("person P@0.5", "person_precision", _f3),
                    ("person R@0.5", "person_recall", _f3),
                    ("retention", "retention", _f3),
                    ("STOP recall", "stop_recall", _f3),
                    ("false-STOP rate", "false_stop_rate", _f3),
                ],
            )
            + "\n"
        )

    parts.append("## Latency (detector call only, CPU, batch 1)\n")
    clean = [r for r in rows if r["kind"] == "clean"]
    parts.append(
        _table(
            clean,
            [
                ("imgsz", "imgsz", _txt),
                ("n", "latency_n", _txt),
                ("mean ms", "latency_mean_ms", _f1),
                ("median ms", "latency_median_ms", _f1),
                ("p95 ms", "latency_p95_ms", _f1),
                ("images/s", "throughput_ips", _f1),
            ],
        )
        + "\n"
    )
    means = {
        size: [float(r["latency_mean_ms"]) for r in rows if int(r["imgsz"]) == size]
        for size in sizes
    }
    parts.append(
        "Spread of mean latency across the ten conditions: "
        + ", ".join(
            f"imgsz {s}: {min(v):.1f}–{max(v):.1f} ms" for s, v in means.items()
        )
        + ".\n"
    )

    parts.append("## Hypothesis checks (mechanical)\n")
    lines = []
    for metric, label in (
        ("person_ap", "person AP"),
        ("person_recall", "person R@0.5"),
    ):
        for kind in ("blur", "low_light", "noise"):
            mono = [
                _monotonic_decreasing(_series(rows, kind, s, metric)) for s in sizes
            ]
            lines.append(
                f"- H1, {label}, {kind}: decreases monotonically with severity at "
                f"{sum(mono)} of {len(sizes)} input sizes."
            )
    for size in sizes:
        worst = {
            kind: _series(rows, kind, size, "person_ap")[-1]
            for kind in ("blur", "low_light", "noise")
        }
        order = sorted(worst, key=worst.get)
        lines.append(
            f"- H1, imgsz {size}: person AP at the strongest level, lowest first: "
            + ", ".join(f"{k} {worst[k]:.3f}" for k in order)
            + "."
        )
    parts.append("\n".join(lines) + "\n")
    parts.append(
        "Figures: `figures/person_ap.png`, `figures/map.png`, "
        "`figures/person_recall.png`, `figures/retention.png`, "
        "`figures/stop_recall.png`, `figures/latency.png`.\n"
    )
    return "\n".join(parts)


SEQUENCE_COLUMNS = [
    ("condition", "condition", _txt),
    ("method", "method", _txt),
    ("precision", "precision", _f3),
    ("recall", "recall", _f3),
    ("transitions/min", "transitions_per_min", _f1),
    ("events found", "events_detected", _txt),
    ("events", "n_events", _txt),
    ("onset s", "onset_mean_s", _f2),
    ("release s", "release_mean_s", _f2),
    ("false-STOP episodes", "false_stop_episodes", _txt),
]


def _h3_checks(rows: list[dict[str, str]], filtered: str) -> list[str]:
    lines = []
    for seq in dict.fromkeys(r["sequence"] for r in rows if r["role"] == "evaluation"):
        pairs = []
        for cond in dict.fromkeys(r["condition"] for r in rows if r["sequence"] == seq):
            by = {
                r["method"]: r
                for r in rows
                if r["sequence"] == seq and r["condition"] == cond
            }
            pairs.append((by["baseline"], by[filtered]))
        fewer = sum(
            float(f["transitions_per_min"]) < float(b["transitions_per_min"])
            for b, f in pairs
        )
        later = [
            float(f["onset_mean_s"]) - float(b["onset_mean_s"])
            for b, f in pairs
            if not (
                math.isnan(float(f["onset_mean_s"]))
                or math.isnan(float(b["onset_mean_s"]))
            )
        ]
        more_missed = sum(
            int(f["events_missed"]) > int(b["events_missed"]) for b, f in pairs
        )
        lines.append(
            f"- H3, {seq}: filter has fewer transitions/min in {fewer} of "
            f"{len(pairs)} conditions; onset delay change "
            + (f"{min(later):+.2f} to {max(later):+.2f} s" if later else "n/a")
            + f"; more missed events in {more_missed} of {len(pairs)} conditions."
        )
    return lines


def sequence_summary(
    rows: list[dict[str, str]],
    sweep_summary: list[dict[str, str]],
    adopted: dict,
    fault_rows: list[dict[str, str]] | None,
    fault_rates: tuple[float, float] | None = None,
) -> str:
    parts = [HEADER, "# Sequence experiment (MOT17, temporal filter)\n"]
    parts.append(
        "GT-STOP: pedestrian (visible ≥ 0.5) in the corridor ROI, box height "
        "≥ ROI minimum. Correctness counts UNKNOWN as STOP. Events are GT-STOP "
        f"runs after merging gaps shorter than {EVENT_MERGE_GAP} frames.\n"
    )
    parts.append("## Filter sweep (tuning sequence, mean over conditions)\n")
    parts.append(
        _table(
            sweep_summary,
            [
                ("n_on", "n_on", _txt),
                ("k", "k_window", _txt),
                ("m_off", "m_off", _txt),
                ("missed events", "events_missed", _f2),
                ("transitions/min", "transitions_per_min", _f1),
                ("onset s", "onset_mean_s", _f2),
            ],
        )
        + "\n"
    )
    a = adopted["adopted"]
    parts.append(
        f"Adopted setting by the declared rule: n_on={a['n_on']}, "
        f"k_window={a['k_window']}, m_off={a['m_off']} "
        + (
            "(differs from the default 3/5/5).\n"
            if adopted["changed"]
            else "(the default).\n"
        )
    )
    filtered = "filtered_adopted" if adopted["changed"] else "filtered"
    for seq in dict.fromkeys(r["sequence"] for r in rows):
        role = next(r["role"] for r in rows if r["sequence"] == seq)
        subset = [
            r
            for r in rows
            if r["sequence"] == seq and r["method"] in ("baseline", filtered)
        ]
        parts.append(f"## {seq} ({role})\n")
        parts.append(_table(subset, SEQUENCE_COLUMNS) + "\n")
    parts.append("## Hypothesis checks (mechanical)\n")
    parts.append("\n".join(_h3_checks(rows, filtered)) + "\n")
    if fault_rows:
        missing, error = fault_rates or (float("nan"), float("nan"))
        parts.append(
            f"## Fault injection ({missing:.0%} MISSING, {error:.0%} ERROR)\n".replace(
                "%", " %"
            )
        )
        parts.append(
            _table(
                fault_rows,
                [
                    ("sequence", "sequence", _txt),
                    *SEQUENCE_COLUMNS[1:],
                    ("UNKNOWN frames", "n_unknown", _txt),
                ],
            )
            + "\n"
        )
    parts.append(
        "Figures: `figures/sequence_transitions.png`, `figures/sequence_onset.png`, "
        "`figures/sequence_recall.png`, `figures/sweep.png`.\n"
    )
    return "\n".join(parts)
